as_number(node: Node) -> Option[float]:
    match node:
        case Node.integer(value, _):
            return Some(float(value))
        case Node.decimal(value, _, _):
            return Some(value)
        case Node.measure(value, _):
            return Some(value)
        case _:
            return None

span_at(src: bytes, offset: int) -> ast.Span:
    line = 1
    col = 1
    index = 0
    size = len(src)
    stop = offset
    if stop > size:
        stop = size
    while index < stop:
        if src[index] == 10:
            line = line + 1
            col = 1
        else:
            col = col + 1
        index = index + 1
    return ast.Span(line=line, col=col, offset=offset)

lex_failure(src: bytes, problem: tk.LexError) -> ParseError:
    span = span_at(src, problem.offset)
    message = problem.message
    if len(message) == 0:
        message = "unexpected character"
    return ParseError(message=message, line=span.line, col=span.col, offset=problem.offset)

parse_int(token: tk.Token, next_pos: int) -> Result[Step, ParseError]:
    match int(token.text):
        case Some(value):
            return Ok(Step(node=ast.Node.integer(value, token.span), next=next_pos))
        case None:
            return Err(invalid_number(token))

parse_float(token: tk.Token, next_pos: int) -> Result[Step, ParseError]:
    match float(token.text):
        case Some(value):
            return Ok(Step(node=ast.Node.decimal(value, token.span), next=next_pos))
        case None:
            return Err(invalid_number(token))

parse_unit(src: bytes, token: tk.Token, next_pos: int) -> Result[Step, ParseError]:
    text = token.text
    number_text = text
    scale = 1.0
    if text.endswith("mil"):
        number_text = text[0:len(text) - 3]
        scale = mil_to_mm()
    elif text.endswith("mm"):
        number_text = text[0:len(text) - 2]
    elif text.endswith("in"):
        number_text = text[0:len(text) - 2]
        scale = in_to_mm()
    elif source_has_mil_suffix(src, token):
        scale = mil_to_mm()
    elif source_has_in_suffix(src, token):
        scale = in_to_mm()
    match float(number_text):
        case Some(value):
            mm_value = value * scale
            return Ok(Step(node=ast.Node.measure(mm_value, token.span), next=next_pos))
        case None:
            return Err(invalid_number(token))

si_scale(letter: str) -> float:
    if letter == "k":
        return 1e3
    if letter == "M":
        return 1e6
    if letter == "G":
        return 1e9
    if letter == "m":
        return 1e-3
    if letter == "u":
        return 1e-6
    if letter == "n":
        return 1e-9
    if letter == "p":
        return 1e-12
    return 1.0

is_si_number_char(ch: str, index: int) -> bool:
    if ch.isdigit():
        return True
    if ch == ".":
        return True
    if ch == "-" and index == 0:
        return True
    return False

parse_si(token: tk.Token, next_pos: int) -> Result[Step, ParseError]:
    text = token.text
    end = si_number_end(text)
    # A missing prefix or a suffixless text cannot be scaled; the tokenizer's
    # suffix rules make this unreachable for a real si_val token.
    if end == 0 or end == len(text):
        return Err(invalid_number(token))
    match float(text[0:end]):
        case Some(value):
            scaled = value * si_scale(text[end])
            # Keep the source spelling alongside the decoded value, exactly as
            # Zig's `Node.suffixedFloat` does: `100nF` and `100n` are the same
            # number, but only the first says which physical quantity it is.
            return Ok(Step(node=ast.Node.decimal(scaled, token.span, Some(text)), next=next_pos))
        case None:
            return Err(invalid_number(token))

parse_node(cursor: Cursor, depth: int) -> Result[Step, ParseError]:
    token = cursor.tokens[cursor.pos]
    next_pos = cursor.pos + 1
    match token.kind:
        case tk.Kind.lparen:
            return parse_list(cursor, next_pos, depth, token.span)
        case tk.Kind.rparen:
            return Err(located(token.span, "unexpected ')' — no matching '(' is open here"))
        case tk.Kind.atom:
            return Ok(Step(node=ast.Node.atom(token.text, token.span), next=next_pos))
        case tk.Kind.string:
            return Ok(Step(node=ast.Node.string(token.text, token.span), next=next_pos))
        case tk.Kind.int_val:
            return parse_int(token, next_pos)
        case tk.Kind.float_val:
            return parse_float(token, next_pos)
        case tk.Kind.unit_val:
            return parse_unit(cursor.src, token, next_pos)
        case tk.Kind.si_val:
            return parse_si(token, next_pos)
        case tk.Kind.eof:
            return Err(located(token.span, "unexpected end of input — a '(' was never closed"))

parse_list(cursor: Cursor, pos: int, depth: int, open_span: ast.Span) -> Result[Step, ParseError]:
    if depth >= cursor.cap:
        return Err(located(open_span, "s-expression nesting is too deep"))
    entries: list[ast.Node] = []
    cursor_pos = pos
    while True:
        token = cursor.tokens[cursor_pos]
        # Point an unterminated list at the `(` that was never closed — the
        # actionable location, not the end of the file where scanning stopped.
        if token.kind == tk.Kind.eof:
            return Err(located(open_span, "unexpected end of input — a '(' was never closed"))
        if token.kind == tk.Kind.rparen:
            cursor_pos = cursor_pos + 1
            break
        child = parse_node(Cursor(src=cursor.src, tokens=cursor.tokens, pos=cursor_pos, cap=cursor.cap), depth + 1)?
        entries.append(child.node)
        cursor_pos = child.next
    return Ok(Step(node=ast.Node.form(entries, open_span), next=cursor_pos))

advance(lx: Lexer):
    if lx.pos < len(lx.src):
        if lx.src[lx.pos] == 10:
            lx.line = lx.line + 1
            lx.col = 1
        else:
            lx.col = lx.col + 1
        lx.pos = lx.pos + 1

si_suffix_len(lx: Lexer) -> int:
    c0 = peek(lx)
    if is_scale_letter(c0):
        c1 = peek_at(lx, 1)
        if not is_atom_continue(c1):
            return 1
        if is_unit_letter(c1) and not is_atom_continue(peek_at(lx, 2)):
            return 2
        return 0
    if is_unit_required_scale(c0):
        if is_unit_letter(peek_at(lx, 1)) and not is_atom_continue(peek_at(lx, 2)):
            return 2
        return 0
    if is_unit_letter(c0) and not is_atom_continue(peek_at(lx, 1)):
        return 1
    return 0

read_string(lx: Lexer, line: int, col: int, offset: int) -> Result[Token, LexError]:
    advance(lx)  # skip opening "
    start = lx.pos
    closed = False
    while lx.pos < len(lx.src) and not closed:
        ch = lx.src[lx.pos]
        if ch == 92:
            advance(lx)  # skip backslash
            advance(lx)  # skip escaped char
        elif ch == 34:
            closed = True
        else:
            advance(lx)
    if not closed:
        return Err(LexError(message="unterminated string", offset=offset, line=line))
    text = lexeme(lx.src, start, lx.pos)
    advance(lx)  # skip closing "
    return Ok(Token(kind=Kind.string, text=text, span=ast.Span(line=line, col=col, offset=offset)))

read_atom(lx: Lexer, line: int, col: int, offset: int) -> Token:
    start = lx.pos
    while is_atom_continue(peek(lx)):
        advance(lx)
    return Token(kind=Kind.atom, text=lexeme(lx.src, start, lx.pos), span=ast.Span(line=line, col=col, offset=offset))

read_operator(lx: Lexer, line: int, col: int, offset: int) -> Token:
    start = lx.pos
    advance(lx)
    if peek(lx) == 61:
        advance(lx)
    return Token(kind=Kind.atom, text=lexeme(lx.src, start, lx.pos), span=ast.Span(line=line, col=col, offset=offset))

read_number(lx: Lexer, line: int, col: int, offset: int) -> Token:
    start = lx.pos
    if peek(lx) == 45:
        advance(lx)
    while is_digit(peek(lx)):
        advance(lx)
    is_float = False
    if peek(lx) == 46 and is_digit(peek_at(lx, 1)):
        is_float = True
        advance(lx)  # skip .
        while is_digit(peek(lx)):
            advance(lx)
    num_end = lx.pos
    # Dimension units: the token text stops before the suffix.
    if peek(lx) == 109:
        if peek_at(lx, 1) == 109 and not is_atom_continue(peek_at(lx, 2)):
            advance(lx)
            advance(lx)
            return Token(kind=Kind.unit_val, text=lexeme(lx.src, start, num_end), span=ast.Span(line=line, col=col, offset=offset))
        if peek_at(lx, 1) == 105 and peek_at(lx, 2) == 108 and not is_atom_continue(peek_at(lx, 3)):
            advance(lx)
            advance(lx)
            advance(lx)
            return Token(kind=Kind.unit_val, text=lexeme(lx.src, start, num_end), span=ast.Span(line=line, col=col, offset=offset))
    # `in` (inch) is a dimension suffix too, on the same end-of-token rule:
    # `10in` is a unit while `10index`, `10in1` and `input` stay atoms.
    if peek(lx) == 105 and peek_at(lx, 1) == 110 and not is_atom_continue(peek_at(lx, 2)):
        advance(lx)
        advance(lx)
        return Token(kind=Kind.unit_val, text=lexeme(lx.src, start, num_end), span=ast.Span(line=line, col=col, offset=offset))
    # SI scale (or a bare unit letter); the text keeps the suffix verbatim so
    # the parser can apply the scale.
    suffix = si_suffix_len(lx)
    if suffix > 0:
        step = 0
        while step < suffix:
            advance(lx)
            step = step + 1
        return Token(kind=Kind.si_val, text=lexeme(lx.src, start, lx.pos), span=ast.Span(line=line, col=col, offset=offset))
    # Percent literal: only when the sign ends the token, so a standalone `%`
    # still lexes as an operator atom.
    if peek(lx) == 37 and not is_atom_continue(peek_at(lx, 1)):
        advance(lx)
        return Token(kind=Kind.si_val, text=lexeme(lx.src, start, lx.pos), span=ast.Span(line=line, col=col, offset=offset))
    if is_atom_continue(peek(lx)):
        while is_atom_continue(peek(lx)):
            advance(lx)
        return Token(kind=Kind.atom, text=lexeme(lx.src, start, lx.pos), span=ast.Span(line=line, col=col, offset=offset))
    text = lexeme(lx.src, start, lx.pos)
    if is_float:
        return Token(kind=Kind.float_val, text=text, span=ast.Span(line=line, col=col, offset=offset))
    return Token(kind=Kind.int_val, text=text, span=ast.Span(line=line, col=col, offset=offset))

tokenize(src: bytes) -> Result[list[Token], LexError]:
    lx = Lexer(src=src, pos=0, line=1, col=1)
    tokens: list[Token] = []
    while True:
        # Skip whitespace and `;` comments to end of line.
        skipping = True
        while skipping:
            byte = peek(lx)
            if is_space(byte):
                advance(lx)
            elif byte == 59:
                while peek(lx) != -1 and peek(lx) != 10:
                    advance(lx)
            else:
                skipping = False
        line = lx.line
        col = lx.col
        offset = lx.pos
        byte = peek(lx)
        if byte == -1:
            tokens.append(Token(kind=Kind.eof, text="", span=ast.Span(line=line, col=col, offset=offset)))
            return Ok(tokens)
        if byte == 40:
            advance(lx)
            tokens.append(Token(kind=Kind.lparen, text="(", span=ast.Span(line=line, col=col, offset=offset)))
        elif byte == 41:
            advance(lx)
            tokens.append(Token(kind=Kind.rparen, text=")", span=ast.Span(line=line, col=col, offset=offset)))
        elif byte == 34:
            match read_string(lx, line, col, offset):
                case Ok(token):
                    tokens.append(token)
                case Err(problem):
                    return Err(problem)
        elif is_digit(byte) or (byte == 45 and is_digit(peek_at(lx, 1))):
            tokens.append(read_number(lx, line, col, offset))
        elif is_atom_start(byte):
            tokens.append(read_atom(lx, line, col, offset))
        elif is_operator_char(byte):
            tokens.append(read_operator(lx, line, col, offset))
        else:
            return Err(LexError(message="unexpected character", offset=offset, line=line))

measured_width(text: str, fallback: int) -> int:
    if len(text) == 0:
        return fallback
    return len(text)

decimal_width(value: float) -> int:
    text = str(value)
    if text.endswith(".0"):
        return measured_width(text[0:len(text) - 2], fallback_float_width)
    return measured_width(text, fallback_float_width)

estimate_width(node: ast.Node, depth: int) -> Option[int]:
    if depth > 3:
        return None
    match node:
        case ast.Node.form(entries, _):
            total = 2
            index = 0
            while index < len(entries):
                if index > 0:
                    total = total + 1
                match estimate_width(entries[index], depth + 1):
                    case Some(width):
                        total = total + width
                    case None:
                        return None
                index = index + 1
            return Some(total)
        case ast.Node.atom(text, _):
            return Some(len(text))
        case ast.Node.string(content, _):
            return Some(len(content) + 2)
        case ast.Node.integer(value, _):
            return Some(int_width(value))
        case ast.Node.decimal(value, _, literal):
            match literal:
                case Some(text):
                    return Some(literal_width(text))
                case None:
                    return Some(decimal_width(value))
        case ast.Node.measure(value, _):
            return Some(measure_width(value))

render(nodes: list[ast.Node]) -> str:
    parts: list[str] = []
    index = 0
    while index < len(nodes):
        if index > 0:
            parts.append("\n")
        push_node(parts, nodes[index], 0)
        index = index + 1
    return "".join(parts)
